import numpy as np
def run_bold_correlation(pcc_ts, dlpfc_ts, scrubbing_mask=None):
    if scrubbing_mask is not None:
        pcc_ts = pcc_ts[scrubbing_mask]
        dlpfc_ts = dlpfc_ts[scrubbing_mask]
    return np.corrcoef(pcc_ts, dlpfc_ts)[0, 1]

